document.addEventListener('DOMContentLoaded', function() {
	// ===== Активные табы в хедере =====
	function updateActiveTab() {
		const menuLinks = document.querySelectorAll('.menu__link');
		const sections = document.querySelectorAll('section[id]');
		
		menuLinks.forEach(link => link.classList.remove('menu-active'));
		
		let currentSection = '';
		const scrollPos = window.scrollY + 150;
		sections.forEach(section => {
			const sectionTop = section.offsetTop;
			const sectionHeight = section.offsetHeight;
			
			if (scrollPos >= sectionTop && scrollPos < sectionTop + sectionHeight) {
				currentSection = section.id;
			}
		});
		
		if (currentSection) {
			const activeLink = document.querySelector(`.menu__link[href*="#${currentSection}"]`);
			if (activeLink) {
				activeLink.classList.add('menu-active');
			}
		}
	}

	// ===== Header scroll effect =====
	const header = document.querySelector(".header");
	if (header) {
		window.addEventListener("scroll", () => {
			let scrollY = window.scrollY;
			if (scrollY > 90) {
				header.classList.add("header--scrolling");
			} else {
				header.classList.remove("header--scrolling");
			}
			updateActiveTab();
		});
	}

	// ===== Обработка формы контактов =====
	const contactForm = document.getElementById('contact-form');
	if (contactForm) {
		contactForm.addEventListener('submit', function(e) {
			e.preventDefault();
			
			const form = this;
			const submitBtn = form.querySelector('.form__submit');
			const submitText = form.querySelector('.form__submit-text');
			const submitLoading = form.querySelector('.form__submit-loading');
			const successMessage = form.querySelector('.form__message--success');
			const errorMessage = form.querySelector('.form__message--error');
			
			if (successMessage) successMessage.style.display = 'none';
			if (errorMessage) errorMessage.style.display = 'none';
			
			if (submitText) submitText.style.display = 'none';
			if (submitLoading) submitLoading.style.display = 'inline';
			if (submitBtn) submitBtn.disabled = true;
			
			fetch(form.action, {
				method: 'POST',
				body: new FormData(form),
				headers: {
					'Accept': 'application/json'
				}
			})
			.then(response => {
				if (response.ok) {
					if (successMessage) successMessage.style.display = 'block';
					form.reset();
				} else {
					throw new Error('Ошибка отправки');
				}
			})
			.catch(error => {
				if (errorMessage) errorMessage.style.display = 'block';
			})
			.finally(() => {
				if (submitText) submitText.style.display = 'inline';
				if (submitLoading) submitLoading.style.display = 'none';
				if (submitBtn) submitBtn.disabled = false;
			});
		});
	}

	// ===== Mobile Menu =====
	const burgerBtn = document.querySelector(".burger-btn");
	const mobileMenuOverlay = document.querySelector(".mobile-menu-overlay");
	const mobileMenuLinks = document.querySelectorAll(".mobile-menu__link");
	const body = document.body;

	// Function to close menu
	function closeMobileMenu() {
		if (mobileMenuOverlay && burgerBtn) {
			mobileMenuOverlay.classList.remove("active");
			burgerBtn.classList.remove("active");
			body.style.overflow = '';
		}
	}

	// Function to open menu
	function openMobileMenu() {
		if (mobileMenuOverlay && burgerBtn) {
			mobileMenuOverlay.classList.add("active");
			burgerBtn.classList.add("active");
			body.style.overflow = 'hidden';
		}
	}

	// Toggle menu on burger button click
	if (burgerBtn && mobileMenuOverlay) {
		burgerBtn.addEventListener("click", (e) => {
			e.preventDefault();
			e.stopPropagation();
			
			const isOpen = mobileMenuOverlay.classList.contains("active");
			
			if (isOpen) {
				closeMobileMenu();
			} else {
				openMobileMenu();
			}
		});

		// Close on background click
		mobileMenuOverlay.addEventListener("click", (e) => {
			if (e.target === mobileMenuOverlay) {
				closeMobileMenu();
			}
		});

		// Close on link click
		mobileMenuLinks.forEach((link) => {
			link.addEventListener("click", () => {
				closeMobileMenu();
			});
		});

		// Close on Escape key
		document.addEventListener("keydown", (e) => {
			if (e.key === "Escape" && mobileMenuOverlay.classList.contains("active")) {
				closeMobileMenu();
			}
		});
	}

	// ===== Swiper инициализация =====
	const swiperContainer = document.querySelector(".page__swiper .swiper");
	
	if (swiperContainer && typeof Swiper !== 'undefined') {
		new Swiper(".page__swiper .swiper", {
			autoplay: {
				delay: 0,
				disableOnInteraction: false
			},
			slidesPerView: 2,
			spaceBetween: 0,
			speed: 2500,
			loop: true,
			allowTouchMove: false,
			freeMode: true,
			freeModeMomentum: false,
			breakpoints: {
				480: {
					slidesPerView: 3
				},
				768: {
					slidesPerView: 4
				},
				1024: {
					slidesPerView: 5
				},
				1380: {
					slidesPerView: 6
				}
			}
		});
	} else {
		console.error('Swiper container not found or Swiper library not loaded');
	}

	// ===== Tab functionality =====
	const tabBtn = document.querySelectorAll(".tab__btn");
	const tabWrapper = document.querySelectorAll(".tab__wrapper");

	function openTab(e) {
		const target = e.currentTarget;
		const buttonId = target.dataset.button;
		
		tabBtn.forEach(function(btn) {
			btn.classList.remove("tab__btn--active");
		});
		
		target.classList.add("tab__btn--active");
		
		tabWrapper.forEach(function(wrapper) {
			wrapper.classList.remove("tab__wrapper--active");
		});
		
		const activeWrapper = document.querySelector(`#${buttonId}`);
		if (activeWrapper) {
			activeWrapper.classList.add("tab__wrapper--active");
		}
	}

	if (tabBtn) {
		tabBtn.forEach(function(btn) {
			btn.addEventListener("click", openTab);
		});
	}
});
